    }
}

0605-can-place-flowers:
impl Solution {
    // Space Complexity: O(1)
    pub fn can_place_flowers_1(flowerbed: Vec<i32>, n: i32) -> bool {
        let mut empty = if flowerbed[0] != 0 { 0 } else { 1 };
        let mut n = n;

        for f in flowerbed {
            if f != 0 {
                n -= (empty - 1) / 2;
                empty = 0;
            } else {
                empty += 1;
            }
        }

        n -= empty / 2;

        n <= 0
    }

    // Space Complexity: O(1)
    pub fn can_place_flowers_2(flowerbed: Vec<i32>, n: i32) -> bool {
        let mut flowerbed = flowerbed;
        let mut n = n;

        for i in 0..flowerbed.len() {
            if n == 0 {
                return true;
            }
            if (i == 0 || flowerbed[i - 1] == 0)
                && flowerbed[i] == 0
                && (i == flowerbed.len() - 1 || flowerbed[i + 1] == 0)
            {
                flowerbed[i] = 1;
                n -= 1;
            }
        }

        n == 0
    }

    // Space Complexity: O(n)
    pub fn other_can_place_flowers_3(flowerbed: Vec<i32>, n: i32) -> bool {
        let mut f: Vec<i32> = vec![vec![0], flowerbed, vec![0]]
            .into_iter()
            .flatten()
            .collect();
        let mut n = n;

        for i in 1..f.len() - 1 {
            if f[i - 1] == 0 && f[i] == 0 && f[i + 1] == 0 {
                f[i] = 1;
                n -= 1;
            }
        }

        n <= 0
    }
}

0169-majority-element:
use std::collections::HashMap;

impl Solution {
    // Time Complexity: O(n)
    // Space Complexity: O(1)
    // Boyer - Moore Algorithm
    pub fn majority_element(nums: Vec<i32>) -> i32 {
        let (mut res, mut count) = (0, 0);

        for n in nums {
            if count == 0 {
                res = n;
            }
            count += if n == res { 1 } else { -1 };
        }
        res
    }

    // Time Complexity: O(n)
    // Space Complexity: O(n)
    // Hashmap
    pub fn majority_element_2(nums: Vec<i32>) -> i32 {
        let mut count = HashMap::new();

        let (mut res, mut max_count) = (0, 0);

        for num in nums {
            *count.entry(num).or_insert(0) += 1;
            res = if *count.get(&num).unwrap() > max_count {
                num
            } else {
                res
            };
            max_count = i32::max(*count.get(&num).unwrap(), max_count);
        }
        res
    }

    // Time Complexity: O(nlogn)
    // Space Complexity: O(1)
    // Sorting
    pub fn majority_element_3(nums: Vec<i32>) -> i32 {
        // Since we are assured that there will be a majority element which occurs more than nums.len() / 2 times, majority element will be at nums.len() / 2 index
        let mut nums = nums;
        nums.sort();
        nums[nums.len() / 2]
    }
}

0496-next-greater-element-i:
use std::collections::HashMap;

impl Solution {
    pub fn next_greater_element(nums1: Vec<i32>, nums2: Vec<i32>) -> Vec<i32> {
        let map: HashMap<i32, usize> = nums1
            .iter()
            .cloned()
            .enumerate()
            .map(Self::reverse_tuple)
            .collect();

        let mut result = vec![0; nums1.len()];

        for (index, val) in nums2.iter().enumerate() {
            if map.contains_key(val) {
                let idx = *map.get(val).unwrap();

                let next_greater = nums2.iter().skip(index).find(|&x| x > val).unwrap_or(&-1);

                result[idx] = *next_greater;
            }
        }
        result
    }

    // O(nums1.length + nums2.length)
    pub fn other_next_greater_element(nums1: Vec<i32>, nums2: Vec<i32>) -> Vec<i32> {
        let map: HashMap<i32, usize> = nums1
            .iter()
            .cloned()
            .enumerate()
            .map(Self::reverse_tuple)
            .collect();

        let mut result = vec![-1; nums1.len()];
        let mut stack = Vec::new();

        for (_, val) in nums2.iter().enumerate() {
            while !stack.is_empty() && val > stack.last().unwrap() {
                let value = stack.pop().unwrap();
                let idx = *map.get(&value).unwrap();
                result[idx] = value;
            }
            if map.contains_key(val) {
                stack.push(*val);
            }
        }
        result
    }

    pub fn reverse_tuple<T, U>(tup: (T, U)) -> (U, T)
    where
        T: Default,
        U: Default,
    {
        let mut new_tup: (U, T) = (U::default(), T::default());
        new_tup.0 = tup.1;
        new_tup.1 = tup.0;
        new_tup
    }
}

