struct Solution;
// @lc code=start
impl Solution {
    pub fn sort_array(nums: Vec<i32>) -> Vec<i32> {
        if nums.len() > 1 {
            let (l, r) = nums.split_at(nums.len() / 2);
            let sorted_r = Self::sort_array(r.to_vec());
            let sorted_l = Self::sort_array(l.to_vec());

            let mut res: Vec<i32> = nums.into();
            let (mut i, mut j) = (0, 0);

            let mut k = 0;
            while i < sorted_l.len() && j < sorted_r.len() {
                if sorted_l[i] <= sorted_r[j] {
                    res[k] = sorted_l[i].clone();
                    i += 1;
                } else {
                    res[k] = sorted_r[j].clone();
                    j += 1;
                }
                k += 1;
            }
            while i < sorted_l.len() {
                res[k] = sorted_l[i].clone();
                i += 1;
                k += 1
            }
            while j < sorted_r.len() {
                res[k] = sorted_r[j].clone();
                j += 1;
                k += 1;
            }
            res
        } else {
            nums
        }
    }
}
// @lc code=end
fn main() {
    let v = vec![-2,3,-5];
    println!("{:?}", Solution::sort_array(v));
}

0347-top-k-frequent-elements:
use std::collections::HashMap;
use std::cmp::Ordering;

impl Solution {
    pub fn top_k_frequent(nums: Vec<i32>, k: i32) -> Vec<i32> {
        let mut map: HashMap<i32, i32> = HashMap::new();

        for n in nums{
            *map.entry(n).and_modify(|val| *val+=1).or_default();
        }

        let mut freq: Vec<(i32, i32)> = map.into_iter().collect();

        let res = match (k as usize).cmp(&freq.len()){
            Ordering::Equal => &freq,
            _ => quick_select(&mut freq, k),
        };

        res.into_iter()
        .map(|&n| n.0)
        .collect()
    }
}

pub fn quick_select(slice: &mut [(i32, i32)], k: i32) -> &[(i32, i32)]{
    let (mut pivot, mut i, mut j) = (0, 1, 1);

    for index in 1..slice.len(){
        if slice[index].1 >= slice[pivot].1{
            slice.swap(index, j);
        }else{
            slice.swap(index, i);
            i+=1;
        }
        j+=1;
    }

    slice.swap(pivot, i - 1);
    pivot = i - 1;

    let larger_items = (j - pivot) as i32;

    match larger_items.cmp(&k) {
        Ordering::Less => quick_select(&mut slice[0..j], k),
        Ordering::Greater => quick_select(&mut slice[pivot + 1..j], k),
        Ordering::Equal => &slice[pivot..j],
    }
}

