use std::collections::HashSet;


impl Solution {
    pub fn is_valid_sudoku(board: Vec<Vec<char>>) -> bool {

       let mut row: HashSet<char> = HashSet::new();
       let mut col: HashSet<char> = HashSet::new();
       let mut bx : HashSet<char> = HashSet::new();

        for i in 0..9{
            for j in 0..9{
                let r = board[i][j];
                let c = board[j][i];
                let b = board[i / 3 * 3 + j / 3][i % 3 * 3 + j % 3];

                if r != '.'{
                    if !row.insert(r){
                        return false;
                    }
                }

                if c != '.'{
                    if !col.insert(c){
                        return false;
                    }
                }

                if b != '.'{
                    if !bx.insert(b){
                        return false;
                    }
                }
            }

            row.clear();
            col.clear();
            bx.clear();
        }

        true
    }
}

0271-encode-and-decode-strings:
struct Codec {}

impl Codec {
    fn new() -> Self {
        Self {}
    }

    fn encode(&self, strs: Vec<String>) -> String {
        let mut store = String::new();

        for s in strs{
            let len = s.len() as u8;

            store.push(len as char);
            store.push_str(&s);
        }

        store
    }

    fn decode(&self, s: String) -> Vec<String> {
        let s: Vec<char> = s.chars().collect();
        let mut i = 0;

        let mut res = vec![];
        while i < s.len(){
            let len = s[i] as u8 as usize;
            i+=1;

            let j = i + len;

            if j <= s.len(){
                let slice = &s[i..i + len];
                res.push(slice.into_iter().collect::<String>());
            }

            i+=len;
        }

        res
    }
}

