        let mut result = 0;
        let mut ranges: [(i32, i32); 26] = [(-1, -1); 26];

        for (i, c) in s.chars().enumerate() {
            let ix = Solution::char_to_index(c) as usize;
            if ranges[ix].0 == -1 {
                ranges[ix].0 = i as i32;
            }
            if i as i32 > ranges[ix].1 {
                ranges[ix].1 = i as i32;
            }
