                let mut set: u32 = 0;
                for c in s[range.0 as usize + 1..range.1 as usize].chars() {
                    set |= 1 << Solution::char_to_index(c);
                }
                result += set.count_ones() as i32;
            }
        }

        result
    }

    pub fn char_to_index(c: char) -> u32 {
        c as u32 - 'a' as u32
    }
}

