            })
            .fold(HashMap::new(), |mut dict, t| {
                dict.entry(t).and_modify(|cnt| *cnt += 1).or_insert(1);
                dict
            })
            .into_iter()
            .filter(|(_, v)| *v > 1)
            .map(|(_, v)| v)
            .fold(0, |mut cnt, v| {
