use std::ops::{Index, IndexMut};
struct CharVec(Vec<i32>);

impl CharVec {
    fn new() -> Self {
        Self(vec![0; 26])
    }
}

impl Index<char> for CharVec {
    type Output = i32;
    fn index(&self, index: char) -> &Self::Output {
        match index {
            'a'..='z' => &self.0[(index as u8 - 'a' as u8) as usize],
            _ => panic!("[!!] {} character is not supported in CharVec", index),
        }
    }
}

impl IndexMut<char> for CharVec {
    fn index_mut(&mut self, index: char) -> &mut Self::Output {
        match index {
            'a'..='z' => &mut self.0[(index as u8 - 'a' as u8) as usize],
            _ => panic!("[!!] {} character is not supported in CharVec", index),
        }
    }
}

impl Eq for CharVec {}

impl PartialEq for CharVec {
    fn eq(&self, other: &Self) -> bool {
        self.0.eq(&other.0)
    }
}

impl Solution {
    pub fn find_anagrams(s: String, p: String) -> Vec<i32> {
        let (s_len, p_len) = (s.len(), p.len());
        let mut ans = vec![];
        if s_len < p_len {
            return ans;
        }
        let mut freq_s = CharVec::new();
        let mut freq_p = CharVec::new();
        let s = s.chars().collect::<Vec<char>>();
        let p = p.chars().collect::<Vec<char>>();
        for i in 0..p_len {
            freq_s[s[i]] += 1;
            freq_p[p[i]] += 1;
        }
        if freq_s == freq_p {
            ans.push(0);
        }
        /* sliding window with of length p_len */
        for i in p_len..s_len {
            freq_s[s[i - p_len]] -= 1;
            freq_s[s[i]] += 1;
            if freq_s == freq_p {
                ans.push((i - p_len + 1) as i32);
            }
        }
        ans
    }
}

0028-find-the-index-of-the-first-occurre:
impl Solution {
    // Time O(m+n) - Space O(n)
    pub fn str_str(haystack: String, needle: String) -> i32 {
        let m = haystack.len();
        let n = needle.len();
        let h_chars: Vec<char> = haystack.chars().collect();
        let n_chars: Vec<char> = needle.chars().collect();
        // Base case, empty needle.
        if n == 0 {
            return 0;
        }
        // LPS generation section.
        let mut lps: Vec<usize> = vec![0; n];
        let (mut left, mut right) = (0, 1);
        while right < n {
            if n_chars[left] == n_chars[right] {
                // If the characters match the lps is one character longer.
                lps[right] = left + 1;
                left += 1;
                right += 1;
            } else if left == 0 {
                // If they don't match and the left pointer is at the start,
                // no characters match.
                lps[right] = 0;
                right += 1;
            } else {
                // Otherwise, we need to check the previous lps.
                left = lps[left - 1];
            }
        }
        // Here we start the KMP proper.
        let (mut haystack_idx, mut needle_idx) = (0, 0);
        while haystack_idx < m {
            if h_chars[haystack_idx] == n_chars[needle_idx] {
                haystack_idx += 1;
                needle_idx += 1;
            } else if needle_idx == 0 {
                haystack_idx += 1;
            } else {
                needle_idx = lps[needle_idx - 1];
            }
            if needle_idx == n {
                return (haystack_idx - n) as i32;
            }
        }
        -1
    }
}

