impl Solution {
    pub fn merge_k_lists(lists: Vec<Option<Box<ListNode>>>) -> Option<Box<ListNode>> {
        fn merge(list1: Option<Box<ListNode>>, list2: Option<Box<ListNode>>) -> Option<Box<ListNode>> {
            match (list1, list2) {
                (None, None) => None,
                (None, Some(l)) | (Some(l), None) => Some(l),
                (Some(l1), Some(l2)) => {
                    if l1.val < l2.val {
                        return Some(Box::new(ListNode {
                            val: l1.val,
                            next: merge(l1.next, Some(l2)),
                        }));
                    }
                    Some(Box::new(ListNode {
                        val: l2.val,
                        next: merge(Some(l1), l2.next),
                    }))
                }
            }
        }

        if lists.is_empty() {
            return None;
        }

        let mut lists = lists;

        while lists.len() > 1 {
            let mut merged = vec![];
            for i in (0..lists.len()).step_by(2) {
                let l1 = lists[i].take();
                let l2 = if i + 1 < lists.len() {
                    lists[i + 1].take()
                } else {
                    None
                };
                merged.push(merge(l1, l2))
            }
            lists = merged;
        }

        lists[0].take()
    }
}

0025-reverse-nodes-in-k-group:
impl Solution {
    pub fn reverse_k_group(head: Option<Box<ListNode>>, k: i32) -> Option<Box<ListNode>> {
        let mut dummy = Some(Box::new(ListNode {next: head, val: 0 }));
        let mut cur = dummy.as_mut();

        'outer: loop {
            let mut start = cur.as_mut().unwrap().next.take();
            if start.is_none() {
                break 'outer;
            }

            let mut end = start.as_mut();
            for _ in 0..(k - 1) {
                end = end.unwrap().next.as_mut();

                if end.is_none() {
                    cur.as_mut().unwrap().next = start;
                    break 'outer;
                }
            }

            let mut tail = end.as_mut().unwrap().next.take();
            let end = Solution::reverse(start, tail);
            cur.as_mut().unwrap().next = end;

            for _ in 0..k {
                cur = cur.unwrap().next.as_mut()
            }
        }
        dummy.unwrap().next
    }

    fn reverse(
        mut head: Option<Box<ListNode>>,
        tail: Option<Box<ListNode>>,
    ) -> Option<Box<ListNode>> {
        let mut prev = tail;
        let mut cur = head;

        while let Some(mut cur_node) = cur {
            let mut next = cur_node.next.take();
            cur_node.next = prev.take();
            prev = Some(cur_node);
            cur = next
        }
        prev
    }
}

