        let mut stones_heap = std::collections::BinaryHeap::new();
        for stone in stones {
            stones_heap.push(stone);
        }

        while stones_heap.len() > 1 {
            let first = stones_heap.pop().unwrap();
            let second = stones_heap.pop().unwrap();
            stones_heap.push(first - second);
        }

