use std::collections::VecDeque;

impl Solution {
    pub fn largest_path_value(colors: String, edges: Vec<Vec<i32>>) -> i32 {
        let n = colors.len();
        let mut graph = vec![vec![]; n];
        let mut indegree = vec![0; n];

        for edge in edges {
            let u = edge[0] as usize;
            let v = edge[1] as usize;
            graph[u].push(v);
            indegree[v] += 1;
        }

        let mut queue = VecDeque::new();
        for i in 0..n {
            if indegree[i] == 0 {
                queue.push_back(i);
            }
        }

        let mut color_count = vec![vec![0; 26]; n];
        let mut visited = 0;
        let colors = colors.as_bytes();
        let mut max_color_value = 0;

        while let Some(node) = queue.pop_front() {
            visited += 1;
            let color_index = (colors[node] - b'a') as usize;
            color_count[node][color_index] += 1;
            max_color_value = max_color_value.max(color_count[node][color_index]);

            for &neigh in &graph[node] {
                for i in 0..26 {
                    color_count[neigh][i] = color_count[neigh][i].max(color_count[node][i]);
                }
                indegree[neigh] -= 1;
                if indegree[neigh] == 0 {
                    queue.push_back(neigh);
                }
            }
        }

        if visited != n as i32 {
            return -1;
        }

        max_color_value
    }
}

0127-word-ladder:
pub fn encode(word : String) -> u64 {
    word.into_bytes().into_iter().fold(0, |mut acc, c|{
        acc <<= 5;
        acc | (c - b'a' + 1) as u64
    })
}

use std::collections::HashSet;
use std::collections::VecDeque;

impl Solution {
    pub fn ladder_length(begin_word: String, end_word: String, word_list: Vec<String>) -> i32 {
        let word_len = begin_word.len();
        let begin_word = encode(begin_word);
        let end_word = encode(end_word);

        let mut word_list : HashSet<u64> = word_list.into_iter().map(|word| encode(word)).collect();
        let mut frontier : VecDeque<u64> = VecDeque::with_capacity(5000);
        let mut seen : HashSet<u64> = HashSet::new();
        let mut res = 1;

        frontier.push_back(begin_word);
        while !frontier.is_empty() {
            let len = frontier.len();
            for _ in 0..len {
                let curr = frontier.pop_front().unwrap();
                if curr == end_word {
                    return res;
                }

                for i in 0..word_len {
                    let filter = !(0b11111 << (i * 5));
                    for character in 1..=26 {
                        let neighbour = ((curr & filter) | (character << (i * 5)));
                        if word_list.contains(&neighbour) && !seen.contains(&neighbour) {
                            frontier.push_back(neighbour);
                            seen.insert(neighbour);
                        }
                    }
                }

            }
            res += 1;
        }
        0
    }
}

