use std::cmp::Reverse;
use std::collections::{BinaryHeap, HashMap};

impl Solution {
    pub fn find_itinerary(tickets: Vec<Vec<String>>) -> Vec<String> {
        let mut graph: HashMap<&str, BinaryHeap<Reverse<&str>>> = HashMap::new();
        for ticket in tickets.iter() {
            graph
                .entry(&ticket[0])
                .or_insert_with(BinaryHeap::new)
                .push(Reverse(&ticket[1]));
        }
        let mut answer: Vec<String> = Vec::with_capacity(tickets.len() + 1);
        let mut stack: Vec<&str> = vec!["JFK"];
        while let Some(src) = stack.last() {
            if let Some(dsts) = graph.get_mut(src) {
                if !dsts.is_empty() {
                    if let Some(dst) = dsts.pop() {
                        stack.push(dst.0);
                    }
                    continue;
                }
            }
            if let Some(last) = stack.pop() {
                answer.push(last.to_string());
            }
        }
        answer.reverse();
        answer
    }
}

0778-swim-in-rising-water:
// https://leetcode.com/problems/swim-in-rising-water/submissions/1011351676/
// Faster than 100% and less memory than 100%

use std::collections::BinaryHeap;
#[derive(Eq, PartialEq)]
struct State {
    t: i32,
    i: usize,
    j: usize,
}

impl Ord for State {
    fn cmp(&self, other: &Self) -> std::cmp::Ordering {
        other.t.cmp(&self.t)
    }
}

impl PartialOrd for State {
    fn partial_cmp(&self, other: &Self) -> Option<std::cmp::Ordering> {
        Some(self.cmp(other))
    }
}


impl Solution {
    pub fn swim_in_water(grid: Vec<Vec<i32>>) -> i32 {
        // Problem Description: You are given an n x n integer matrix grid where each value grid[i][j] represents the elevation at that point (i, j).
        // The rain starts to fall. At time t, the depth of the water everywhere is t. You can swim from a square to another 4-directionally adjacent square if and only if the elevation of both squares individually are at most t. You can swim infinite distances in zero time. Of course, you must stay within the boundaries of the grid during your swim.
        // Return the least time until you can reach the bottom right square (n - 1, n - 1) if you start at the top left square (0, 0).
        let n = grid.len();
        let mut visited = vec![vec![false; n]; n];
        let mut heap = BinaryHeap::new();
        heap.push(State {
            t: grid[0][0],
            i: 0,
            j: 0,
        });
        let mut min_t = 0;
        // want to find the min time that can reach the bottom right square
        while let Some(State { t, i, j }) = heap.pop() {
            min_t = min_t.max(t);
            if i == n - 1 && j == n - 1 {
                return min_t;
            }
            for (di, dj) in [(1, 0), (0, 1), (-1, 0), (0, -1)].iter() {
                let ni = i as i32 + di;
                let nj = j as i32 + dj;
                if ni >= 0
                    && ni < n as i32
                    && nj >= 0
                    && nj < n as i32
                    && !visited[ni as usize][nj as usize]
                {
                    heap.push(State {
                        t: grid[ni as usize][nj as usize],
                        i: ni as usize,
                        j: nj as usize,
                    });
                    visited[ni as usize][nj as usize] = true;
                }
            }
        }
        min_t
    }
}

2421-number-of-good-paths:
use std::{cmp::Ordering, collections::HashMap};

struct UnionFind {
    parent: Vec<usize>,
    rank: Vec<i32>,
}

impl UnionFind {
    fn new(n: usize) -> Self {
        UnionFind {
            parent: (0..n).collect(),
            rank: vec![0; n],
        }
    }

    fn find(&mut self, mut i: usize) -> usize {
        while i != self.parent[i] {
            self.parent[i] = self.parent[self.parent[i]];
            i = self.parent[i];
        }
        i
    }

    fn union(&mut self, a: usize, b: usize) -> bool {
        let a_root = self.find(a);
        let b_root = self.find(b);

        if a_root == b_root {
            return false;
        }
        match self.rank[a_root].cmp(&self.rank[b_root]) {
            Ordering::Less => {
                self.parent[a_root] = b_root;
                self.rank[b_root] += self.rank[a_root];
            }
            _ => {
                self.parent[b_root] = a_root;
                self.rank[a_root] = self.rank[b_root];
            }
        }
        true
    }
}

impl Solution {
    pub fn number_of_good_paths(vals: Vec<i32>, edges: Vec<Vec<i32>>) -> i32 {
        let adj = Self::create_adj_list(&edges);
        let val_to_index = Self::create_val_to_index(&vals);

        let mut res = 0;
        let mut uf = UnionFind::new(vals.len());

        let mut keys: Vec<i32> = val_to_index.keys().cloned().collect();
        keys.sort();

        for val in keys {
            for i in val_to_index.get(&val).unwrap_or(&vec![]) {
                for nei in adj.get(&(*i as i32)).unwrap_or(&vec![]) {
                    if vals[*nei as usize] <= vals[*i] {
                        uf.union(*nei as usize, *i);
                    }
                }
            }
            let mut count = HashMap::new();
            for i in val_to_index.get(&val).unwrap() {
                *count.entry(uf.find(*i)).or_insert(0) += 1;
                res += count.get(&uf.find(*i)).unwrap();
            }
        }

        res
    }

    pub fn create_adj_list(edges: &Vec<Vec<i32>>) -> HashMap<i32, Vec<i32>> {
        let mut adj = HashMap::new();

        for edge in edges {
            let a = edge[0];
            let b = edge[1];

            adj.entry(a).or_insert(vec![]).push(b);
            adj.entry(b).or_insert(vec![]).push(a);
        }

        adj
    }

    pub fn create_val_to_index(vals: &Vec<i32>) -> HashMap<i32, Vec<usize>> {
        let mut val_to_index = HashMap::new();

        for (i, val) in vals.iter().enumerate() {
            val_to_index.entry(*val).or_insert(vec![]).push(i);
        }

        val_to_index
    }
}

