        for i in 1..word.len() {
            let (prefix, suffix) = (&word[..i], &word[i..]);
            if (word_set.contains(prefix) && word_set.contains(suffix))
                || (word_set.contains(prefix) && Self::dfs(suffix, word_set))
            {
                return true;
            }
        }
        false
    }
}

