impl Solution {
    pub fn my_pow(x: f64, n: i32) -> f64 {
        fn helper(x: f64, n: i32) -> f64 {
            match (x, n) {
                (0.0, _) => 0.0,
                (_, 0) => 1.0,
                _ => {
                    let res = helper(x * x, n / 2);
                    if n % 2 == 0 {
                        res
                    } else {
                        x * res
                    }
                }
            }
        }

        let res = helper(x, n.abs());

        if n >= 0 {
            res
        } else {
            1.0 / res
        }
    }
}

0043-multiply-strings:
impl Solution {
    pub fn multiply(num1: String, num2: String) -> String {
        if num1 == "0" || num2 == "0" {
            return String::from('0');
        }

        let n1 = num1.chars().rev().collect::<String>();
        let n2 = num2.chars().rev().collect::<String>();
        let mut res = vec![0; n1.len() + n2.len()];
        for (i1, c1) in n1.chars().enumerate() {
            for (i2, c2) in n2.chars().enumerate() {
                let digit = (c1.to_digit(10).unwrap_or(0) * c2.to_digit(10).unwrap_or(0));
                res[i1 + i2] += digit;
                res[i1 + i2 + 1] += res[i1 + i2] / 10;
                res[i1 + i2] %= 10;
            }
        }

        while let Some(&0) = res.last() {
            res.pop();
        }

        res.into_iter()
            .rev()
            .map(|digit| char::from_digit(digit as u32, 10).unwrap())
            .collect()
    }
}

2013-detect-squares:
use std::collections::HashMap;

struct DetectSquares {
    points: Vec<(i32, i32)>,
    counts: HashMap<(i32, i32), i32>
}

impl DetectSquares {

    fn new() -> Self {
        Self {
            points: vec![],
            counts: HashMap::new()
        }
    }

    fn add(&mut self, point: Vec<i32>) {
        let p = (point[0], point[1]);
        self.points.push(p);
        *self.counts.entry(p).or_default() += 1;
    }

    fn count(&self, point: Vec<i32>) -> i32 {
        let mut res = 0;
        let (px, py) = (point[0], point[1]);
        for (x, y) in self.points.iter() {
            if (py - y).abs() != (px - x).abs() || *x == px || *y == py {
                continue;
            }
            res += self.counts.get(&(*x, py)).unwrap_or(&0) * self.counts.get(&(px,*y)).unwrap_or(&0);
        }

        res
    }
}

