1470-shuffle-the-array:
impl Solution {
    pub fn shuffle(nums: Vec<i32>, n: i32) -> Vec<i32> {
        let mut nums = nums;

        for i in 0..n as usize {
            nums[i] = nums[i] << 10;
            nums[i] = nums[i] | nums[i + n as usize];
        }

        let mut j = 2 * n - 1;

        for i in (0..=n as usize - 1).rev() {
            let y = nums[i] & (2_i32.pow(10) - 1);
            let x = nums[i] >> 10;
            nums[j as usize] = y;
            nums[j as usize - 1] = x;
            j -= 2;
        }

        nums
    }
}

0989-add-to-array-form-of-integer:
impl Solution {
    pub fn add_to_array_form(num: Vec<i32>, k: i32) -> Vec<i32> {
        let mut num: Vec<i32> = num.into_iter().rev().collect();
        let mut k = k;
        let mut i = 0;

        while k > 0 {
            let digit = k % 10;

            if i < num.len() {
                num[i] += digit;
            } else {
                num.push(digit);
            }

            let carry = num[i] / 10;
            num[i] = num[i] % 10;

            k /= 10;
            k += carry;
            i += 1;
        }

        num.into_iter().rev().collect()
    }
}

